from taf.ue.fastmile.exceptions import IperfPortInvalid

THROUGHPUT_UNIT = "k"


class IperfDataTransferConfig(object):

    def __init__(self, dt_definition, configuration, ue_ip, logger):
        """
        Data transfer settings from DataTransferDefinition (robot kwargs).
        :param dt_definition: object that encapsulates all needed parameters
        :type dt_definition: DataTransferDefinition class object
        :param configuration: configuration of MediaTek UE
        :type configuration: dict
        """
        self._dt_definition = dt_definition
        self._configuration = configuration
        self._ue_ip = ue_ip
        self.logger = logger
        self.default_iperf_binary = "iperf3" if self.version == "3" else "iperf"
        self.dt_config = self._init_dt_config()

    @property
    def direction(self):
        """Direction of data transfer ('ul', 'dl')"""
        return self._dt_definition.direction

    @property
    def version(self):
        version = str(self._configuration.get("version"))
        if version not in ("2", "3"):
            version = "2"
        return version

    @property
    def app_bind(self):
        """Return Ip for iperf -B option"""
        bind_interface_ip = self._configuration["app_server"].get("bind_interface_ip")
        if bind_interface_ip:
            bind_interface_ip = bind_interface_ip.strip()
            return None if bind_interface_ip == '' else bind_interface_ip
        return None

    @property
    def app_iperf_connection_ip(self):
        """
        Returns ip of iperf server to which iperf client should connect to
        Returns binding interface ip if set or default iperf server ip
        """
        return self.app_bind or self._configuration["app_server"].get("address")

    @property
    def ue_bind(self):
        """Return Ip for iperf -B option"""
        return self._ue_ip.strip()

    @property
    def ue_iperf_connection_ip(self):
        """
        Returns ip of iperf server to which iperf client should connect to
        Returns binding interface ip if set or default iperf server ip
        """
        return self.ue_bind or self._ue_ip

    def _get_binary_path(self, binary_path):
        """Return Iperf binary path"""
        return binary_path or self.default_iperf_binary

    def _check_if_port_valid_for_appserver(self, iperf_port):
        iperf_ports_from_config = self._configuration["app_server"]["ports"]
        if iperf_ports_from_config:
            iperf_ports_from_config = [int(each_iperf_port) for each_iperf_port in iperf_ports_from_config]
            if iperf_port not in iperf_ports_from_config:
                msg = "traffic port {} should be in app server ports {}".format(iperf_port, iperf_ports_from_config)
                raise IperfPortInvalid(msg)

    def _get_iperf_port(self):
        default_iperf_port = 5001 if self.version == "2" else 5201
        iperf_port = self._dt_definition.protocol_details.get("port", None)
        iperf_port = iperf_port if iperf_port is None else int(iperf_port)
        if iperf_port:
            if self.direction == "ul":
                self._check_if_port_valid_for_appserver(iperf_port)
            return iperf_port
        return default_iperf_port

    def _init_dt_config(self):
        protocol_details = self._dt_definition.protocol_details
        dt_config = {
            "app_server": {
                "host_configuration": {
                    "host": self._configuration["app_server"]["address"],
                    "username": self._configuration["app_server"]["user"],
                    "password": self._configuration["app_server"]["password"]},
                "version": self.version,
                "mode": "server" if self.direction == "ul" else "client",
                "binary_path": self._get_binary_path(self._configuration["app_server"]["binary_path"])},
            "ue_host": {
                "version": self.version,
                "mode": "server" if self.direction == "dl" else "client",
                "binary_path": self._get_binary_path(self._configuration["binary_path"])},
            "protocol": self._dt_definition.protocol,
            "time": self._dt_definition.duration,
            "bandwidth": "{}{}".format(self._dt_definition.throughput, THROUGHPUT_UNIT),
            "port": self._get_iperf_port(),
            "length": protocol_details.get("packet", None) or protocol_details.get("packet_size", None),
            "interval": protocol_details.get("interval", 1),
            "parallel": (protocol_details.get("parallel", None)
                         or protocol_details.get("parallel_streams", None)
                         or protocol_details.get("parallel_thread", None)),
            "ttl": protocol_details.get("ttl", None),
            "window": protocol_details.get("buffer", None),
            "max_segment_size": protocol_details.get("max_segment_size", None),
            "reverse": protocol_details.get("reverse", None),
            "linux_congestion": protocol_details.get("linux_congestion", None),
        }
        self.logger.debug("dt_config: {}".format(dt_config))
        return dt_config

    def _create_iperf_common_options(self, bind):
        options = "-p {} -i {} -f k ".format(self.dt_config["port"], self.dt_config["interval"])
        options += self._add_arg_to_cmd("-B", bind)
        return options

    def _create_iperf2_common_options(self, bind):
        options = ""
        if self.dt_config["protocol"] == "udp":
            options = "-u "
        options += self._create_iperf_common_options(bind)

        options += self._add_arg_to_cmd("-l", self.dt_config["length"])
        options += self._add_arg_to_cmd("-M", self.dt_config["max_segment_size"])
        options += self._add_arg_to_cmd("-w", self.dt_config["window"])
        return options

    def _create_iperf2_client_options(self, bind, client):
        options = "-c {} ".format(client)
        options += self._create_iperf2_common_options(bind)
        options += "-t {} ".format(self.dt_config["time"])

        if "-u" in options:
            options += "-b {} ".format(self.dt_config["bandwidth"])

        options += self._add_arg_to_cmd("-P", self.dt_config["parallel"])
        options += self._add_arg_to_cmd("-T", self.dt_config["ttl"])
        options += self._add_arg_to_cmd("-Z", self.dt_config["linux_congestion"])
        return options

    def _create_iperf2_server_options(self, bind):
        options = "-s "
        options += self._create_iperf2_common_options(bind)
        return options

    def _create_iperf3_client_options(self, bind, client):
        options = "-c {} ".format(client)
        if self.dt_config["protocol"] == "udp":
            options += "-u "
        options += self._create_iperf_common_options(bind)
        options += "-t {} ".format(self.dt_config["time"])
        options += "-b {} ".format(self.dt_config["bandwidth"])

        options += self._add_arg_to_cmd("-l", self.dt_config["length"])  # noqa: C901
        options += self._add_arg_to_cmd("-M", self.dt_config["max_segment_size"])
        options += self._add_arg_to_cmd("-w", self.dt_config["window"])
        options += self._add_arg_to_cmd("-P", self.dt_config["parallel"])
        options += self._add_arg_to_cmd("-R", self.dt_config["reverse"])
        options += self._add_arg_to_cmd("-C", self.dt_config["linux_congestion"])
        return options

    def _create_iperf3_server_options(self, bind):
        options = "-s "
        options += self._create_iperf_common_options(bind)
        return options

    @staticmethod
    def _add_arg_to_cmd(flag, value):
        if value is not None:
            return "{} {} ".format(flag, value)
        return ""

    @staticmethod
    def _create_dt_config(config, cmd_options):
        dt_config = {"cmd_options": cmd_options}
        dt_config.update(config)
        return dt_config

    def create_uplink_dt_config(self):
        if self.version == "2":
            server_options = self._create_iperf2_server_options(bind=self.app_bind)
            client_options = self._create_iperf2_client_options(bind=self.ue_bind, client=self.app_iperf_connection_ip)
        else:
            server_options = self._create_iperf3_server_options(bind=self.app_bind)
            client_options = self._create_iperf3_client_options(bind=self.ue_bind, client=self.app_iperf_connection_ip)

        app_dt_config = self._create_dt_config(self.dt_config["app_server"], server_options)
        ue_dt_config = self._create_dt_config(self.dt_config["ue_host"], client_options)
        return app_dt_config, ue_dt_config

    def create_downlink_dt_config(self):
        if self.version == "2":
            server_options = self._create_iperf2_server_options(bind=self.ue_bind)
            client_options = self._create_iperf2_client_options(bind=self.app_bind, client=self.ue_iperf_connection_ip)
        else:
            server_options = self._create_iperf3_server_options(bind=self.ue_bind)
            client_options = self._create_iperf3_client_options(bind=self.app_bind, client=self.ue_iperf_connection_ip)

        app_dt_config = self._create_dt_config(self.dt_config["app_server"], client_options)
        ue_dt_config = self._create_dt_config(self.dt_config["ue_host"], server_options)
        return app_dt_config, ue_dt_config
